https://forms.cloud.microsoft/r/2Y9qZJUUdS?origin=lprLink no pide validar nada es publicaComo tu encuesta es pública y no requiere inicio de sesión, el proceso con puppeteer-extra y el plugin stealth es bastante directo.Los formularios de Microsoft Forms cargan sus elementos de forma dinámica usando contenedores especiales en lugar de etiquetas HTML estándar (como <select> o <input type="radio"> tradicionales). Para interactuar con ellos de forma segura sin que la automatización falle por problemas de carga, debemos buscar los textos de las respuestas usando selectores avanzados.Aquí tienes un script base en Node.js configurado detalladamente para abrir tu encuesta, responder preguntas de opción múltiple, campos de texto y finalmente presionar enviar:Código de Automatización para Microsoft Formsjavascriptconst puppeteer = require('puppeteer-extra');
const StealthPlugin = require('puppeteer-extra-plugin-stealth');

// Activamos el plugin stealth para evitar bloqueos por comportamiento robotizado
puppeteer.use(StealthPlugin());

(async () => {
  // Lanza el navegador. Cambia headless a true si no quieres ver la ventana abriéndose.
  const browser = await puppeteer.launch({ 
    headless: false,
    args: ['--start-maximized'] 
  });
  
  const page = await browser.newPage();
  
  // Ajustamos el tamaño de la pantalla visible
  await page.setViewport({ width: 1366, height: 768 });

  try {
    console.log('Navegando a la encuesta de Microsoft Forms...');
    await page.goto('https://cloud.microsoft', {
      waitUntil: 'networkidle2', // Espera a que la red esté completamente inactiva
      timeout: 60000
    });

    // 1. EJEMPLO PARA SELECCIONAR UNA OPCIÓN MÚLTIPLE (Radio Button o Checkbox)
    // Buscaremos el contenedor de la opción por medio de su texto visible.
    const opcionDeseada = 'Opción 1'; // <-- Cambia esto por el texto exacto de tu respuesta
    console.log(`Seleccionando la opción: "${opcionDeseada}"...`);
    
    // Esperamos a que los elementos de las respuestas aparezcan en el formulario
    await page.waitForSelector('div[role="radio"], div[role="checkbox"], label', { timeout: 15000 });
    
    // Buscamos el elemento que coincida con el texto de tu respuesta y le hacemos clic
    await page.evaluate((texto) => {
      const elementos = Array.from(document.querySelectorAll('span, label, div'));
      const coincidencia = elementos.find(el => el.textContent.trim() === texto);
      if (coincidencia) {
        coincidencia.click();
      } else {
        throw new Error(`No se encontró la opción con el texto: ${texto}`);
      }
    }, opcionDeseada);

    // Pequeña pausa aleatoria para simular comportamiento humano
    await page.waitForTimeout(Math.random() * 1000 + 500);

    // 2. EJEMPLO PARA ESCRIBIR EN UN CAMPO DE TEXTO (Si tu encuesta tiene uno)
    // Microsoft Forms suele usar elementos <input> o <textarea> dentro de las preguntas
    const textInputSelector = 'input[type="text"], textarea';
    const existeCampoTexto = await page.$(textInputSelector);
    
    if (existeCampoTexto) {
      console.log('Escribiendo en el campo de texto...');
      await page.click(textInputSelector);
      // Escribe simulando pausas aleatorias de teclado (delay) entre letras
      await page.type(textInputSelector, 'Respuesta automatizada de prueba', { delay: 50 });
    }

    // Pausa antes de enviar
    await page.waitForTimeout(1000);

    // 3. ENVIAR EL FORMULARIO
    // Microsoft Forms utiliza botones con un atributo de "submit" o roles específicos.
    console.log('Buscando el botón de Enviar...');
    
    // Buscaremos el botón que tenga la palabra "Enviar" o "Submit"
    await page.evaluate(() => {
      const botones = Array.from(document.querySelectorAll('button'));
      const botonEnviar = botones.find(b => 
        b.textContent.includes('Enviar') || 
        b.textContent.includes('Submit')
      );
      if (botonEnviar) {
        botonEnviar.click();
        console.log('Formulario enviado con éxito.');
      } else {
        console.log('No se encontró el botón de enviar de forma automática. Intentando por selector nativo...');
      }
    });

    // Esperar a que cargue la pantalla de confirmación ("Gracias", etc.)
    await page.waitForNavigation({ waitUntil: 'networkidle2' }).catch(() => {
      // A veces Forms no cambia de URL, solo muta la página interna. Esperamos unos segundos.
      return page.waitForTimeout(3000);
    });
    
    console.log('Proceso finalizado correctamente.');

  } catch (error) {
    console.error('Ocurrió un error durante la ejecución:', error);
  } finally {
    // Cerramos el navegador al terminar
    await browser.close();
  }
})(); que las tendencias sean a jovenes del area agricola que allan hecho compostaje o quieran acerlo y les interese etc

